from collections import deque

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, flow, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.graph[u])):
            ptr[u] = i
            v, cap, rev = self.graph[u][i]
            if self.level[v] == self.level[u] + 1 and cap > 0:
                pushed = self.dfs(v, t, min(flow, cap), ptr)
                if pushed > 0:
                    self.graph[u][i][1] -= pushed
                    self.graph[v][rev][1] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * self.n
            while True:
                pushed = self.dfs(s, t, float('inf'), ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow


def solution(input_text):
    lines = input_text.strip().split('\n')

    n, m = map(int, lines[0].split())
    vertex_weights = list(map(int, lines[1].split()))

    edges = []
    for i in range(2, 2 + m):
        parts = lines[i].split()
        v, u, w = map(int, parts)
        edges.append((v, u, w))

    if m == 0:
        return '0\n'

    total_edge_weight = sum(w for _, _, w in edges)

    # Build graph: source=0, vertices=1 to n, edges=n+1 to n+m, sink=n+m+1
    dinic = Dinic(n + m + 2)
    source = 0
    sink = n + m + 1

    # Add edges from source to each edge node
    for i, (v, u, w) in enumerate(edges):
        edge_node = n + 1 + i
        dinic.add_edge(source, edge_node, w)
        dinic.add_edge(v, edge_node, float('inf'))
        dinic.add_edge(u, edge_node, float('inf'))

    # Add edges from each vertex to sink
    for i, weight in enumerate(vertex_weights):
        dinic.add_edge(i + 1, sink, weight)

    max_flow = dinic.max_flow(source, sink)
    return str(total_edge_weight - max_flow) + '\n'

