    # When we add character c, we transition to new state

    # Precompute transition table for KMP automaton
    # trans[state][char] = next_state after seeing char
    trans = {}
    for state in range(k + 1):  # states 0 to k
        for c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ":
            curr = state
            while curr > 0 and c != virus[curr]:
                curr = curr - 1
                # Rewind using computed prefix function
                if curr == 0:
                    break
            if curr < k and c == virus[curr]:
                curr += 1
            # We'll compute proper transitions below

    # Build prefix function for KMP
    pi = [0] * k
    for i in range(1, k):
        j = pi[i-1]
        while j > 0 and virus[i] != virus[j]:
            j = pi[j-1]
        if virus[i] == virus[j]:
            j += 1
        pi[i] = j

    # Transition function using KMP
    def transition(state, c):
        j = state
        while j > 0 and c != virus[j]:
            j = pi[j-1]
        if c == virus[j]:
            j += 1
        return j

    # DP: dp[i][j][state] = maximum LCS length using s1[:i] and s2[:j]
    #          ending in virus-match state 'state' (but not completing virus)
    INF = 10**9
    dp = [[[-INF] * (k + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    dp[0][0][0] = 0

    # Fill DP table
    for i in range(n + 1):
        for j in range(m + 1):
            for state in range(k + 1):
                if dp[i][j][state] < 0:
                    continue

                # Option 1: Skip character from s1 (possibly add c from s2)
                if i < n:
                    # Try s1[i] == s2[j+1] matching
                    pass

                # Option 2: Skip character from s2  
                if j < m:
                    pass

                # Option 3: Pick both s1[i] and s2[j] if they match
                if i < n and j < m and s1[i] == s2[j]:
                    c = s1[i]
                    new_state = transition(state, c)
                    if new_state < k:  # Don't complete virus
                        dp[i+1][j+1][new_state] = max(
                            dp[i+1][j+1][new_state],
                            dp[i][j][state] + 1
                        )

    # Find maximum valid LCS length
    best = 0
    for idx in range(n + 1):
