        total_cost = 0
        for i in range(n):
            count = bisect.bisect_right(sale_days[i], day)
            needed = k[i]
            if needed <= count:
                total_cost += needed
            else:
                total_cost += count + 2 * (needed - count)
        return total_cost <= day

