import os

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    S = lines[1]
    T = lines[2]

    valid_positions = []

    for start_pos in range(n - m + 1):
        valid = True
        mapping = {}  # s_char -> t_char

        for i in range(m):
            s_char = S[start_pos + i]
            t_char = T[i]

            if s_char in mapping:
                if mapping[s_char] != t_char:
                    valid = False
                    break
            else:
                # Check if t_char is already used by a different s_char
                target_used = any(target == t_char for target in mapping.values())
                if target_used:
                    valid = False
                    break
                mapping[s_char] = t_char

        if valid:
            valid_positions.append(start_pos + 1)  # 1-indexed

    result = str(len(valid_positions)) + "\n"
    if valid_positions:
        result += " ".join(map(str, valid_positions))

    return result

