def solution(input_str):
    parts = input_str.strip().split('\n')
    q = int(parts[0])
    results = []

    idx = 1
    for _ in range(q):
        a, b = map(int, parts[idx].split())
        idx += 1
        s = parts[idx]
        idx += 1

        # Find maximum consecutive dots
        max_gap = 0
        current = 0
        for c in s:
            if c == '.':
                current += 1
                max_gap = max(max_gap, current)
            else:
                current = 0

        # If Alice can't make a move, she loses
        if max_gap < a:
            results.append('NO')
            continue

        # Alice can make a move on a gap of size exactly a
        # After Alice uses up that gap, if all remaining gaps < b, Bob loses
        # Check if there's at least one gap of size exactly a
        has_exact_a = False
        current = 0
        for c in s:
            if c == '.':
                current += 1
            else:
                if current == a:
                    has_exact_a = True
                    # Verify all remaining gaps are < b after this gap is consumed
                    # Look ahead in string
                    after_pos = s.find(c)  # position of X after this gap
                    tail_sum = 0
                    for tail_char in s[after_pos+1:]:
                        if tail_char == '.':
                            tail_sum += 1
                        else:
                            if tail_sum == a:
                                break  # gap >= a exists, Alice can win
                            tail_sum = 0
                    else:
                        # All gaps after are < b
                        if tail_sum < b:
                            has_exact_a = True
                    break
                else:
                    current = 0

        # Alice wins if she can find at least one gap of size >= a
        results.append('YES')

    return '\n'.join(results)

from functools import lru_cache

def solution(input_str):
    # Parse input
    parts = input_str.strip().split()
    a = int(parts[0])
    b = int(parts[1])
    n = int(parts[2])

    @lru_cache(maxsize=None)
    def can_win_boxes_sum(a, b):
        if (a + 1) ** b >= n:
            can_add_box = False
        else:
            can_add_box = True

        if a ** (b + 1) >= n:
            can_add_item = False
        else:
            can_add_item = True

        if not can_add_box and not can_add_item:
            return False

        box_outcome = True
        if can_add_box:
            box_outcome = not can_win_boxes_sum(a + 1, b)

        item_outcome = True
        if can_add_item:
            item_outcome = not can_win_boxes_sum(a, b + 1)

        return box_outcome or item_outcome

    stas_can_win = can_win_boxes_sum(a, b)

    if stas_can_win:
        return "Masha\n\n"
    else:
        return "Stas\n\n"

