    def get_divisors(num):
        divs = set()
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divs.add(i)
                divs.add(num // i)
        return divs

    # Collect all divisors from all array elements
    all_divisors = set()
    for num in arr:
        all_divisors.update(get_divisors(num))

    for g in all_divisors:
        if g == 1:
            continue

        bad_indices = []
        fixable_count = 0

        for i in range(n):
            rem = arr[i] % g
            # Can fix by changing by at most 1 if remainder <= 1 or (g - remainder) <= 1
            if rem > 1 and (g - rem) > 1:
                bad_indices.append(i)
            else:
                # Elements that need changes
                if rem > 0:
                    fixable_count += 1

        if not bad_indices:
            cost = fixable_count * b
        else:
            # Need to remove a subsegment covering all bad indices
            first_bad = bad_indices[0]
            last_bad = bad_indices[-1]
            segment_length = last_bad - first_bad + 1
            cost = segment_length * a + fixable_count * b

        if cost < min_cost:
            min_cost = cost

    return str(min_cost)

